insert into change_headers (id, ts) values (79, '2026-11-27') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (79, 'ru', 'Во всех калькуляторах стрелки ↑ и ↓ меняют число в поле, как обычный спиннер: одно нажатие — один шаг (1 для целых полей, 0,1 для дробных), с Shift шаг умножается на 10, с Ctrl — на 100. Значение останавливается на границах поля, пустое поле начинает от значения по умолчанию, страница при этом не прокручивается.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'en', 'In all calculators, the ↑ and ↓ arrow keys now step the number in a field like a native spinbox: one press is one step (1 for whole-number fields, 0.1 for fractional ones), Shift multiplies the step by 10 and Ctrl by 100. The value stops at the field''s limits, an emptied field starts from its default, and the page no longer scrolls while you step.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'pt', 'Em todas as calculadoras, as setas ↑ e ↓ alteram o número de um campo como um spinner normal: cada pressão é um passo (1 para campos inteiros, 0,1 para decimais), com Shift o passo é multiplicado por 10 e com Ctrl por 100. O valor para nos limites do campo, um campo vazio começa do valor padrão e a página não rola durante a alteração.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'de', 'In allen Rechnern ändern die Pfeiltasten ↑ und ↓ die Zahl im Feld wie ein normales Spin-Feld: ein Tastendruck, ein Schritt (1 für ganze Zahlen, 0,1 für Dezimalfelder), mit Shift wird der Schritt mit 10 multipliziert, mit Strg mit 100. Der Wert stoppt an den Grenzen des Feldes, ein geleertes Feld startet vom Standardwert, und die Seite scrollt dabei nicht.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'pl', 'We wszystkich kalkulatorach strzałki ↑ i ↓ zmieniają liczbę w polu jak zwykły spinner: jedno naciśnięcie to jeden krok (1 dla pól całkowitych, 0,1 dla dziesiętnych), z Shift krok mnoży się przez 10, a z Ctrl przez 100. Wartość zatrzymuje się na granicach pola, puste pole zaczyna od wartości domyślnej, a strona nie przewija się podczas zmiany.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'es', 'En todas las calculadoras, las flechas ↑ y ↓ cambian el número del campo como un control numérico normal: cada pulsación es un paso (1 en los campos enteros, 0,1 en los decimales), con Mayús el paso se multiplica por 10 y con Ctrl por 100. El valor se detiene en los límites del campo, un campo vacío empieza desde su valor predeterminado y la página ya no se desplaza al hacerlo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'fr', 'Dans toutes les calculatrices, les flèches ↑ et ↓ font varier le nombre d''un champ comme un spinbox classique : un appui, un pas (1 pour les champs entiers, 0,1 pour les décimaux), avec Maj le pas est multiplié par 10 et avec Ctrl par 100. La valeur s''arrête aux limites du champ, un champ vidé repart de sa valeur par défaut et la page ne défile plus pendant la manipulation.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'it', 'In tutte le calcolatrici, le frecce ↑ e ↓ modificano il numero di un campo come un normale spinbox: una pressione, un passo (1 per i campi interi, 0,1 per i decimali), con Maiusc il passo è moltiplicato per 10 e con Ctrl per 100. Il valore si ferma ai limiti del campo, un campo svuotato riparte dal valore predefinito e la pagina non scorre durante la modifica.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'nl', 'In alle calculators veranderen de pijltjes ↑ en ↓ het getal in een veld zoals een gewoon spinvak: één druk is één stap (1 voor hele getallen, 0,1 voor decimale velden), met Shift wordt de stap met 10 vermenigvuldigd en met Ctrl met 100. De waarde stopt bij de grenzen van het veld, een leeggemaakt veld begint bij de standaardwaarde en de pagina scrollt niet meer tijdens het wijzigen.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'sk', 'Vo všetkých kalkulačkách šípky ↑ a ↓ menia číslo v poli ako bežný spinner: jedno stlačenie je jeden krok (1 pre celé polia, 0,1 pre desatinné), so Shift sa krok násobí desiatimi a s Ctrl stovkou. Hodnota sa zastaví na hraniciach poľa, vyprázdnené pole začína od predvolenej hodnoty a stránka sa pri tom neposúva.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'tr', 'Tüm hesaplayıcılarda ↑ ve ↓ ok tuşları, alandaki sayıyı normal bir spinner gibi değiştirir: her basış bir adımdır (tam sayı alanlarında 1, ondalık alanlarda 0,1), Shift ile adım 10 katına, Ctrl ile 100 katına çıkar. Değer alanın sınırlarında durur, boşaltılan alan varsayılan değerinden başlar ve sayfa bu sırada kaymaz.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (79, 'bs', 'U svim kalkulatorima strelice ↑ i ↓ mijenjaju broj u polju kao obični spinner: jedan pritisak je jedan korak (1 za cijela polja, 0,1 za decimalna), sa Shift korak se množi sa 10, a sa Ctrl sa 100. Vrijednost se zaustavlja na granicama polja, ispražnjeno polje počinje od zadane vrijednosti i stranica se pri tome ne pomjera.') on duplicate key update description = values(description);
